CAT = "frmotoMaitrise"; SEG = "MAI"
# Maîtrise de la moto : freinage, contre-braquage, évitement, allure lente, adhérence, pluie,
# vent. Sources : arrêté du 23 avril 2012, annexe I, I-6 (freinage d'urgence, contre-braquage,
# évitement, maniement de l'embrayage, des freins et du regard) ; arrêté du 20 avril 2012, art. 2.
Q = [
("Sur sol sec, quel frein fournit la plus grande part du freinage d'une moto ?",
 "Le frein avant", ["Le frein arrière", "Le frein moteur", "Les deux à parts égales"],
 "Au freinage, le poids bascule vers l'avant : la roue avant, plus chargée, peut transmettre la plus grande part de l'effort. On freine des deux, surtout de l'avant."),
("Pour un freinage d'urgence en ligne droite, vous utilisez :",
 "Les deux freins ensemble", ["Le frein arrière seul", "Le frein moteur seul", "Le frein avant d'un coup sec"],
 "Les deux freins combinés donnent la distance la plus courte. Sur l'avant, la pression monte vite mais progressivement pour ne pas bloquer la roue."),
("Pendant un freinage d'urgence, où portez-vous le regard ?",
 "Loin devant, vers l'issue", ["Sur la roue avant de la moto", "Fixement sur l'obstacle", "Dans le rétroviseur gauche"],
 "Regarder l'obstacle attire la moto vers lui. Le regard loin devant, vers l'espace libre, aide à garder la moto droite et à trouver une issue."),
("Que fait l'ABS lors d'un freinage appuyé ?",
 "Il empêche le blocage des roues", ["Il raccourcit toujours le freinage", "Il freine à votre place en courbe", "Il coupe le moteur au freinage"],
 "L'ABS module la pression pour éviter le blocage, ce qui garde la moto dirigeable et stable. Il ne crée pas d'adhérence et ne raccourcit pas toujours la distance."),
("Vous devez freiner fort dans un virage. Que faites-vous d'abord ?",
 "Redresser la moto", ["Freiner fort de l'avant penché", "Débrayer en pleine courbe", "Accélérer puis freiner"],
 "Moto penchée, l'adhérence sert déjà à tenir la courbe. On redresse avant de freiner fort, sinon la roue avant risque de partir."),
("Sans ABS, la roue arrière se bloque au freinage. Votre réaction :",
 "Relâcher un peu le frein", ["Freiner plus fort de l'arrière", "Lâcher le guidon d'une main", "Passer au point mort vite"],
 "Une roue bloquée glisse et ne freine plus bien. Relâcher légèrement la pédale lui rend son adhérence, tout en gardant la moto droite."),
("Pour faire pencher la moto à gauche à vitesse normale, vous poussez :",
 "Le guidon côté gauche", ["Le guidon côté droit", "Sur le repose-pied droit", "Le réservoir avec le genou droit"],
 "C'est le contre-braquage : une poussée sur la poignée gauche fait pencher la moto à gauche. L'annexe I de l'arrêté du 23 avril 2012 l'évalue lors de l'évitement."),
("Un obstacle surgit devant vous. Vous n'avez plus la place de freiner. Vous :",
 "L'évitez par contre-braquage", ["Freinez fort moto penchée", "Fermez les yeux et freinez", "Coupez le contact aussitôt"],
 "Annexe I : le candidat doit maîtriser l'évitement par contre-braquage, puis revenir sur sa trajectoire initiale. Freiner et tourner en même temps fait perdre l'adhérence."),
("À allure très lente, avec quoi contrôlez-vous surtout la vitesse ?",
 "L'embrayage", ["Le frein avant", "La poignée seule", "Le coupe-circuit"],
 "Annexe I : rouler au pas demande d'actionner l'embrayage, si besoin avec l'accélérateur et le frein arrière. Le frein avant à l'arrêt complet fait perdre l'équilibre."),
("Lors d'un demi-tour au pas, quel frein est le plus sûr ?",
 "Le frein arrière", ["Le frein avant", "Les deux freins à fond", "Aucun, au point mort"],
 "Guidon tourné, un coup de frein avant fait plonger et tomber la moto. Le frein arrière, dosé avec l'embrayage, stabilise l'allure lente."),
("Pendant une manœuvre lente guidon tourné, où regardez-vous ?",
 "Là où vous voulez aller", ["Juste devant la roue avant", "Sur vos pieds au sol", "Sur le compteur de vitesse"],
 "Le regard guide la trajectoire : tête tournée vers la sortie de la manœuvre, la moto suit. Fixer le sol fait perdre l'équilibre."),
("Quelle position adoptez-vous pour bien piloter ?",
 "Bras souples, genoux serrés", ["Bras tendus et coudes bloqués", "Sur la pointe des pieds", "Buste raide, penché en avant"],
 "Bras souples et genoux contre le réservoir laissent la direction libre et stabilisent la moto. Des bras raides transmettent chaque secousse au guidon."),
("Au début d'une pluie après des jours secs, la route est surtout :",
 "Très glissante", ["Plus adhérente", "Plus sèche au milieu", "Sans danger"],
 "Les premières gouttes mélangent poussière, huile et gomme en une pellicule grasse. C'est le moment où la chaussée glisse le plus."),
("Sous la pluie, quelles surfaces évitez-vous de prendre penché ?",
 "Les marquages peints", ["L'enrobé rugueux et sec", "Le centre de votre voie", "Le bitume neuf et sec"],
 "Les marquages peints, les plaques d'égout et les rails deviennent très glissants mouillés. On les franchit moto droite, sans freiner ni accélérer."),
("Une plaque d'égout se trouve dans votre trajectoire en courbe. Comment la passez-vous ?",
 "Moto droite, sans freiner", ["En freinant juste dessus", "En accélérant fort dessus", "En penchant davantage"],
 "Le métal offre peu d'adhérence, surtout mouillé. On adapte sa trajectoire pour la franchir avec le moins d'angle possible, sans action brusque."),
("Vous voyez des gravillons à l'entrée d'un virage. Que faites-vous ?",
 "Ralentir avant d'y arriver", ["Freiner fort sur les gravillons", "Accélérer pour passer vite", "Pencher au maximum dessus"],
 "Les gravillons font rouler les pneus comme sur des billes. On réduit l'allure avant, puis on les traverse moto la plus droite possible."),
("Une flaque d'eau profonde couvre la route. Le risque est :",
 "L'aquaplaning", ["Le surrégime moteur", "La crevaison", "Le calage"],
 "Une lame d'eau peut soulever le pneu de la chaussée : il perd le contact et la moto devient incontrôlable. On ralentit avant la flaque."),
("Un vent latéral fort souffle sur un pont. Comment roulez-vous ?",
 "Moins vite, guidon souple", ["Plus vite pour passer", "Bras raides et bloqués", "Debout sur les cale-pieds"],
 "Une rafale pousse la moto. Allure réduite, bras souples et genoux serrés permettent de corriger sans mouvement brusque ; attention en sortant d'un abri."),
("Un poids lourd vous croise sur une route étroite. Que risquez-vous ?",
 "Un souffle qui vous déporte", ["Un blocage de roue arrière", "Un calage soudain du moteur", "Une perte totale des freins"],
 "Le passage d'un camion crée un appel puis un souffle d'air. On anticipe en tenant fermement le guidon et en se décalant sur la droite si c'est possible."),
("Dans une longue descente de col, quel frein utilisez-vous en premier ?",
 "Le frein moteur", ["Le frein avant en continu", "Le frein arrière en continu", "Aucun, roue libre"],
 "Le frein moteur, avec un rapport adapté, retient la moto sans chauffer les freins. Les freins seuls, sollicités longtemps, perdent de leur efficacité."),
("Des feuilles mortes humides couvrent la chaussée en automne. Quel danger créent-elles ?",
 "Une perte d'adhérence", ["Une crevaison du pneu", "Un calage du moteur", "Un phare masqué"],
 "Les feuilles mouillées forment une couche très glissante. On ralentit et on évite de freiner ou de pencher fort dessus."),
("Par temps de verglas annoncé, la meilleure décision pour un motard est :",
 "Ne pas prendre la moto", ["Rouler en seconde partout", "Dégonfler un peu les pneus", "Rouler sur la ligne blanche"],
 "Sur glace, deux roues n'ont presque plus d'adhérence : aucune technique ne compense. On choisit un autre moyen de transport."),
("En freinant, pourquoi rétrograder un rapport à la fois ?",
 "Éviter le blocage arrière", ["Prendre de la vitesse en descente", "Allumer le feu stop arrière", "Économiser la gomme des pneus"],
 "Sauter plusieurs rapports d'un coup crée un frein moteur brutal qui peut faire glisser ou bloquer la roue arrière. On rétrograde rapport par rapport, embrayage relâché en douceur."),
("Sur une route bosselée, votre moto se met à guidonner. Que faites-vous ?",
 "Relâchez vos bras", ["Serrez fort le guidon", "Freinez fort de l'avant", "Accélérez à fond"],
 "Un guidonnage s'amortit mieux bras souples, en réduisant progressivement l'allure. Crisper les bras ou freiner fort l'aggrave."),
("Vous démarrez en côte. Quelle commande vous empêche de reculer ?",
 "Le frein arrière tenu", ["Le frein moteur seul", "Le coupe-circuit", "La béquille latérale"],
 "On maintient la moto au frein arrière, on cherche le point de patinage de l'embrayage en accélérant légèrement, puis on relâche le frein."),
("Une voiture freine brusquement devant vous en ville. Votre premier réflexe :",
 "Freiner des deux freins", ["Klaxonner sans freiner", "Passer vite à sa droite", "Débrayer et attendre"],
 "Le freinage combiné des deux freins est le geste le plus efficace. L'évitement ne s'envisage que si l'espace est libre et la distance insuffisante."),
("Vous roulez avec un passager. Comment change votre distance de freinage ?",
 "Elle augmente", ["Elle diminue", "Elle reste la même", "Elle dépend du klaxon"],
 "Plus de masse à arrêter allonge la distance de freinage. Avec un passager ou des bagages, on laisse plus d'espace devant soi."),
("Pourquoi éviter de freiner en roulant sur une ligne blanche mouillée ?",
 "La roue peut glisser", ["Le feu stop s'éteint", "Le moteur cale", "Le compteur se bloque"],
 "La peinture mouillée offre bien moins d'adhérence que l'enrobé. Freiner dessus peut faire glisser la roue ; on freine avant ou après."),
("Sur une route qui passe de l'ombre au soleil en hiver, que redoutez-vous ?",
 "Du verglas à l'ombre", ["Un pneu trop chaud", "Un éblouissement par la neige", "Une panne d'éclairage"],
 "Les zones à l'ombre, les ponts et les sous-bois gèlent en premier et dégèlent en dernier. On ralentit avant d'y entrer."),
("Votre roue avant chasse sur une tache d'huile en ligne droite. Vous :",
 "Gardez le guidon souple", ["Freinez fort aussitôt", "Tournez vivement", "Coupez le moteur net"],
 "Une action brusque aggrave la glissade. Bras souples et regard loin, la moto retrouve souvent l'adhérence après la tache."),
]
